export const BODY: string = "\n<p>ترچھی تصویر درست کرنے میں سیکنڈ لگتے ہیں، جب آپ کو مراحل معلوم ہوں۔ آپ کو سافٹ ویئر انسٹال کرنے یا اکاؤنٹ بنانے کی ضرورت نہیں، اور پورا کام آپ کے براؤزر میں چلتا ہے۔</p>\n<p>یہ طریقہ اپ لوڈ سے ڈاؤن لوڈ تک عمل بتاتا ہے۔ اس میں فوری 90 درجے موڑ، جھکی ہوئی تصویر کے لیے اپنی مرضی کے زاویے، اور آئینہ سیلفی کے لیے افقی پلٹ شامل ہیں۔</p>\n<p>آخر تک آپ جان جائیں گے کہ ایک تصویر کیسے درست کریں، ان کا پورا بیچ کیسے درست کریں، اور وہ عام غلطیاں جو وقت ضائع کرتی ہیں۔ نتیجہ جانچنے تک اصل فائل پاس رکھیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: آپ کو کیا چاہیے</h2>\n<p>آپ کو خود تصویر فائل چاہیے، اپنے آلے پر محفوظ یا کلپ بورڈ سے چسپاں کرنے کے لیے تیار۔ ٹول 20 MB تک JPG، PNG، WebP، HEIC، GIF، BMP اور SVG فائلیں قبول کرتا ہے۔</p>\n<p>اصل فائل سے کام کریں، اس کاپی سے نہیں جو پہلے گھمائی یا کمپریس کی جا چکی ہو۔ ہر اضافی محفوظ JPG میں تھوڑا نقصان بڑھاتا ہے، اس لیے صاف ترین نتیجہ پہلی ترمیم سے آتا ہے۔</p>\n<p>ٹول کھولنے سے پہلے طے کریں کہ کیا غلط ہے۔ کیا تصویر ترچھی ہے، الٹی ہے، چند درجے جھکی ہے، یا آئینہ ہے؟ جواب بتاتا ہے کہ گھمائیں، پلٹیں، یا دونوں۔</p>\n<h2 id=\"step-by-step\">چھ مراحل میں تصویر گھمائیں</h2>\n<p>عمل ایک تصویر اور بیچ کے لیے ایک جیسا ہے۔ پہلے اپ لوڈ کریں، حرکت چنیں، پیش نظارہ جانچیں، پھر نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>فوری درست کے لیے 90 درجے والے بٹن ہی کافی ہیں۔ جھکے افق کے لیے اپنی مرضی کا زاویہ سلائیڈر استعمال کریں اور اسے گھسیٹتے ہوئے پیش نظارہ دیکھیں۔</p>\n<ol>\n<li>اپنی تصویر ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر، یا Ctrl+V سے چسپاں کر کے اپ لوڈ کریں۔</li>\n<li>معیاری موڑ کے لیے Quick Rotate and Flip کے نیچے Rotate 90° Left، Rotate 90° Right، یا 180° پر کلک کریں۔</li>\n<li>جھکی تصویر کے لیے Rotation Angle سلائیڈر کو مطلوبہ بالکل درجے تک گھسیٹیں، پھر Apply Angle پر کلک کریں۔</li>\n<li>الٹی سیلفی کو آئینہ کرنے کے لیے Flip Horizontal پر کلک کریں، یا الٹی تصویر کو الٹنے کے لیے Flip Vertical پر کلک کریں۔</li>\n<li>سمت کو ساتھ ساتھ جانچنے کے لیے تصویر کارڈ پر Compare پر کلک کریں۔</li>\n<li>ایک فائل کے لیے Download پر کلک کریں، یا پورا بیچ گھمانے پر Download All (ZIP) پر کلک کریں۔</li>\n</ol>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائل جانچیں۔ اسے ایک بار کھولیں، تصدیق کریں کہ سمت درست ہے، اور تب ہی اسے فارم سے منسلک کریں یا پوسٹ کریں۔</p>\n<h2 id=\"choosing-the-right-angle\">درست زاویہ چننا</h2>\n<p>ترچھی دکھائی دینے والی تصویر کو ایک سمت میں 90 درجے چاہییں۔ اگر پہلی کوشش اسے بدتر بنا دے تو دوسری سمت درست ہے، اس لیے واپس کریں اور دوسری طرف موڑیں۔</p>\n<p>الٹی دکھائی دینے والی تصویر کو 180 درجے چاہییں۔ یہاں کوئی ابہام نہیں، کیونکہ آدھا موڑ کسی بھی سمت میں ایک جیسا ہے۔</p>\n<p>جھکے افق کو اپنی مرضی کا زاویہ چاہیے، عام طور پر ایک سے دس درجے کے درمیان۔ چھوٹے قدم بڑے قدموں سے بہتر ہیں، کیونکہ آنکھ ہلکے جھکاؤ کے لیے بھی حساس ہے۔</p>\n<h2 id=\"using-custom-angles\">جھکی تصویر کے لیے اپنی مرضی کے زاویے استعمال کرنا</h2>\n<p>اپنی مرضی کے زاویے ان تصویروں کے لیے ہیں جو بالکل سیدھی نہیں۔ ڈھلوان افق والی ساحل تصویر یا تھوڑی ٹیڑھی بیٹھی اسکین شدہ صفحہ، دونوں اس گروپ میں آتے ہیں۔</p>\n<p>Rotation Angle سلائیڈر آہستہ گھسیٹیں اور افق دیکھیں۔ پیش نظارہ براہ راست اپ ڈیٹ ہوتا ہے، اس لیے جس لمحے لکیر سطح لگے، رک جائیں۔</p>\n<p>قیمت کی تصدیق کے لیے Apply Angle پر کلک کریں، یا دوبارہ شروع کرنے کے لیے Reset to 0° پر کلک کریں۔ ڈاؤن لوڈ سے پہلے آپ جتنی بار چاہیں ایڈجسٹ کر سکتے ہیں، کیونکہ برآمد تک کچھ بھی محفوظ نہیں ہوتا۔</p>\n<h2 id=\"flipping-a-mirrored-selfie\">آئینہ سیلفی پلٹنا</h2>\n<p>آئینہ سیلفی پہچاننا آسان ہے: قمیض پر متن الٹا پڑھتا ہے۔ حل Flip Horizontal پر ایک کلک ہے، جو تصویر کو واپس معمول پر آئینہ کرتا ہے۔</p>\n<p>اگر تصویر کو دونوں حرکتیں چاہییں تو پہلے پلٹیں۔ ترتیب پیش نظارہ جانچنے سے کم اہم ہے، مگر پہلے پلٹنے سے منطق سادہ رہتی ہے۔</p>\n<p>متن سے زیادہ جانچیں۔ پلٹ ہر چیز کو مخالف طرف منتقل کرتا ہے، بشمول بالوں کی مانگ، تل، یا پس منظر کی نشانی، اس لیے پوری تصویر دیکھیں۔</p>\n<h2 id=\"rotating-a-batch\">تصویروں کا پورا بیچ گھمانا</h2>\n<p>وہ تمام تصویریں ایک ساتھ اپ لوڈ کریں جنہیں ایک ہی مسئلہ ہے۔ ٹول آپ کی چنی ہوئی گھماؤ کو قطار کی ہر تصویر پر ایک ساتھ لاگو کرتا ہے۔</p>\n<p>یہ اس وقت بہترین کام کرتا ہے جب سمت کا مسئلہ مستقل ہو۔ مثال کے طور پر پورٹریٹ موڈ میں لی گئی تصویروں کے فولڈر کو سب کو ایک ہی 90 درجے موڑ چاہیے۔</p>\n<p>اگر تصویروں کو مختلف زاویے چاہییں تو انہیں گروپوں میں تقسیم کریں۔ ایک گروپ گھمائیں، اسے ڈاؤن لوڈ کریں، پھر قطار صاف کریں اور اگلا گروپ گھمائیں۔</p>\n<h2 id=\"choosing-output-format\">آؤٹ پٹ فارمیٹ چننا</h2>\n<p>Original فارمیٹ محفوظ ترین انتخاب ہے جب آپ کو صرف سمت درست کرنی ہو۔ یہ فائل قسم کو بغیر تبدیلی کے رکھتا ہے اور دوبارہ انکوڈ کی حیرانیوں سے بچاتا ہے۔</p>\n<p>JPG ان تصویروں کے لیے بہترین انتخاب ہے جنہیں آپ شیئر یا اپ لوڈ کرنے کا ارادہ رکھتے ہیں۔ یہ فائل سائز چھوٹے رکھتا ہے اور ہر جگہ کام کرتا ہے، بشمول پرانے فارم اور پیغام ایپس۔</p>\n<p>PNG اسکرین شاٹ، لوگو اور متن والے گرافکس کے لیے درست انتخاب ہے۔ یہ تیز کنارے اور شفافیت محفوظ رکھتا ہے، جو JPG نہیں کر سکتا۔</p>\n<h2 id=\"checking-your-result\">ڈاؤن لوڈ سے پہلے اپنا نتیجہ جانچنا</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پیش نظارہ دیکھیں۔ Compare بٹن اصل اور گھمائی ہوئی ورژن کو ایک ساتھ دکھاتا ہے، جو درست کی تصدیق کا تیز ترین طریقہ ہے۔</p>\n<p>اپنی مرضی کے زاویے کی گھماؤ کے بعد تصویر کے کنارے دیکھیں۔ پھیلے ہوئے کینوس نے کونے والے حصے شامل کیے ہو سکتے ہیں جن کی آپ کو توقع نہیں تھی، اور آپ انہیں کراپ کرنا چاہیں۔</p>\n<p>فائل سائز بھی جانچیں۔ گھمائی ہوئی JPG اصل سائز کے قریب ہونی چاہیے، اور بڑی چھلانگ عام طور پر مطلب ہے کوالٹی ترتیب یا فارمیٹ بدل گیا۔</p>\n<h2 id=\"fixing-scanned-documents\">اسکین شدہ دستاویز درست کرنا</h2>\n<p>اسکین شدہ صفحے تصویروں کے بعد سب سے عام گھماؤ کام ہیں۔ اسکینر میں الٹا ڈالا گیا صفحہ الٹا نکلتا ہے، اور حل 180 درجے موڑ ہے۔</p>\n<p>ترچھا اسکین شدہ صفحے کے لیے 90 درجے استعمال کریں۔ گھمانے کے بعد متن کی ایک لکیر پڑھیں تاکہ تصدیق ہو کہ وہ بائیں سے دائیں چلتی ہے، جو زیادہ تر دستاویزات کے لیے درست سمت ہے۔</p>\n<p>اسکین میں چھوٹے جھکاؤ بھی عام ہیں۔ اسکینر میں تھوڑا ٹیڑھا بیٹھا صفحہ سیدھا کرنے کے لیے ایک یا دو درجے اپنی مرضی کا زاویہ چاہتا ہے۔</p>\n<h2 id=\"rotating-on-mobile\">فون یا ٹیبلٹ پر تصویریں گھمانا</h2>\n<p>ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ ترچھی تصویر اسی فون پر درست کر سکتے ہیں جس نے وہ لی تھی۔ اپنی گیلری سے اپ لوڈ کریں، گھماؤ بٹن ٹیپ کریں، اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>اپنی مرضی کے زاویوں کے لیے زاویہ سلائیڈر اپنی انگلی سے گھسیٹیں۔ پیش نظارہ اتنا بڑا ہے کہ جھکا افق چھوٹی اسکرین پر بھی پرکھا جا سکے۔</p>\n<p>بیچ گھماؤ موبائل پر بھی کام کرتا ہے، اگرچہ سست کنکشن پر کئی بڑی فائلیں اپ لوڈ کرنے میں زیادہ وقت لگتا ہے۔ جب ممکن ہو تو بڑے بیچ کمپیوٹر پر کریں۔</p>\n<h2 id=\"troubleshooting\">مسئلہ حل کرنا: جب گھماؤ قائم نہ رہے</h2>\n<p>کبھی تصویر ٹول میں درست لگتی ہے مگر ڈاؤن لوڈ کے بعد دوبارہ ترچھی ہو جاتی ہے۔ اس کا عام طور پر مطلب ہے کہ اصل فائل میں EXIF سمت نوٹ تھا جسے ویور اب بھی غلط پڑھ رہا ہے۔</p>\n<p>حل یہ ہے کہ ڈاؤن لوڈ شدہ فائل کو ٹول میں ایک بار اور گھمائیں، یا پکسل واقعی درست ہیں، اس کی تصدیق کے لیے اسے مختلف ویور میں کھولیں۔ ٹول پکسل دوبارہ لکھتا ہے، اس لیے فائل خود درست ہے۔</p>\n<p>دوسرا عام مسئلہ تصویر کا غلط سمت میں گھومنا ہے۔ موڑ واپس کریں اور دوسری طرف گھمائیں، کیونکہ 90 درجے گھڑی کی سمت اور 90 درجے گھڑی کے خلاف مخالف نتائج دیتے ہیں۔</p>\n<h2 id=\"quick-tips\">تیز گھماؤ کے لیے فوری نکات</h2>\n<p>اسکرین شاٹ کو پہلے محفوظ کرنے کی بجائے Ctrl+V سے سیدھا چسپاں کریں۔ ٹول کلپ بورڈ تصویریں قبول کرتا ہے، جو اسکرین کیپچر درست کرتے ہوئے ایک مرحلہ بچاتا ہے۔</p>\n<p>کی بورڈ دوستانہ عادتیں استعمال کریں: اپ لوڈ کریں، گھمائیں، موازنہ کریں، ڈاؤن لوڈ کریں۔ وہی چار حرکتیں تقریباً ہر سمت مسئلے کو سنبھالتی ہیں جس سے آپ ملیں گے۔</p>\n<p>ڈاؤن لوڈ جانچنے تک اصل فائل رکھیں۔ اگر نتیجہ غلط ہو تو آپ صاف اصل سے دوبارہ شروع کر سکتے ہیں، خراب کاپی کو دوبارہ ترمیم کرنے کی بجائے۔</p>\n<h2 id=\"rotating-animated-gifs\">متحرک GIF گھمانا</h2>\n<p>متحرک GIF گھمائے جا سکتے ہیں، مگر نتیجہ ٹول اور فائل پر منحصر ہے۔ Rotate and Flip ٹول GIF فائلیں قبول کرتا ہے، اور گھماؤ حرکت فریموں پر لاگو ہوتا ہے۔</p>\n<p>GIF گھمانے کے بعد نتیجہ احتیاط سے جانچیں۔ کچھ حرکتوں میں کئی فریم ہوتے ہیں، اور پہلے فریم پر درست لگنے والی گھماؤ کو بعد والے فریموں پر بھی جانچنا چاہیے۔</p>\n<p>فائل سائز ذہن میں رکھیں۔ پہلے سے بڑی GIF دوبارہ رینڈر کے بعد تھوڑی بڑھ سکتی ہے، اس لیے شیئر کرنے سے پہلے ڈاؤن لوڈ شدہ سائز کا اصل سے موازنہ کریں۔</p>\n<h2 id=\"rotation-for-id-photos\">شناختی اور پاسپورٹ تصویر گھمانا</h2>\n<p>شناختی تصویریں سیدھی، سامنے والی اور درست فریم والی ہونی چاہییں، اور ترچھی شناختی تصویر سیدھی مسترد ہو جائے گی۔ گھماؤ حل ہے، مگر اسے احتیاط سے کرنا چاہیے۔</p>\n<p>گھمانے سے پہلے پورٹل قواعد جانچیں۔ کچھ پورٹل درست سمت کے ساتھ ساتھ بالکل پکسل ابعاد بھی مانگتے ہیں، اس لیے 90 درجے موڑ آپ کو چاہیے ابعاد بدل سکتا ہے۔</p>\n<p>اصل تصویر گھمائیں، اس کاپی کو نہیں جو پہلے کمپریس کی جا چکی ہو۔ شناختی تصویر کو تیز چہرہ چاہیے، اور ہر اضافی محفوظ ان تفصیل کو نرم کرتا ہے جنہیں پورٹل جانچتا ہے۔</p>\n<h2 id=\"rotation-shortcuts\">کی بورڈ اور کلپ بورڈ شارٹ کٹ</h2>\n<p>Ctrl+V سے چسپاں کرنا اسکرین شاٹ کو ٹول میں لانے کا تیز ترین طریقہ ہے۔ کسی بھی پروگرام سے تصویر کاپی کریں، اسے سیدھا ڈراپ زون میں چسپاں کریں، اور محفوظ کرنے والا مرحلہ مکمل چھوڑ دیں۔</p>\n<p>اپنے آلے پر پہلے سے موجود فائلوں کے لیے انہیں ڈراپ زون میں گھسیٹنا فولڈر براؤز کرنے سے تیز ہے۔ ایک فائل یا پورا بیچ ایک ساتھ ڈالیں۔</p>\n<p>ہر گھماؤ کے بعد Compare بٹن استعمال کریں، صرف آخر میں نہیں۔ ہر تبدیلی کے بعد فوری جانچ غلط سمت موڑ کو ڈاؤن لوڈ شدہ غلطی بننے سے پہلے پکڑتی ہے۔</p>\n<h2 id=\"rotation-vs-other-tools\">گھماؤ بمقابلہ دوسرے ترمیم ٹول</h2>\n<p>گھماؤ سمت بدلتا ہے، مگر سائز، رنگ یا تیزی نہیں بدلتا۔ اگر تصویر بہت بڑی، بہت گہری یا بہت پھیکی ہے تو صرف گھماؤ اسے درست نہیں کرے گا۔</p>\n<p>جب تصویر کو فارم یا پروفائل کے لیے نئے ابعاد چاہییں تو گھماؤ کو <a href=\"/ur/tasveer-resize-karein/\">Image Resizer</a> کے ساتھ جوڑیں۔ گھمانے کے بعد سائز بدلیں، تاکہ ابعاد نئی سمت سے میل کھائیں۔</p>\n<p>جب ترچھی تصویر بہت گہری بھی ہو تو اسے <a href=\"/ur/tasveer-ki-brightness-badlein/\">Image Brightness Editor</a> کے ساتھ جوڑیں۔ گھمانے کے بعد روشن کرنے سے ورک فلو سادہ اور نتیجہ متوقع رہتا ہے۔</p>\n<p>جب گھمائی ہوئی تصویر میں خالی کونے یا خلل ڈالنے والا کنارہ ہو تو اسے <a href=\"/ur/tasveer-crop-karein/\">Image Cropper</a> کے ساتھ جوڑیں۔ سمت طے ہونے کے بعد آخر میں کراپ کریں، تاکہ فریمنگ حتمی شکل سے میل کھائے۔</p>\n<p>تصویریں خود کیوں گھومتی ہیں، اس کی مکمل وضاحت کے لیے <a href=\"/ur/blog/tasveer-orientation-exif-rotation/\">Image Orientation: EXIF Rotation Problems Explained</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-ghumana-ultana-rehnumai/\">Rotate and Flip Images: Complete Guide</a> دیکھیں، اور اگر گھمائی ہوئی تصویر کو تراشنا ہو تو <a href=\"/ur/tasveer-crop-karein/\">Image Cropper</a> استعمال کریں۔</p>\n";

